event: step.delta
data: {"index":1,"delta":{"text":", Johannes Gutenberg’s printing press did more than simply mechanize book production; it fundamentally rewired human consciousness. By breaking","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" the barriers of distance, time, and class, it ensured that ideas could travel freely, empowering the individual and shaping the modern","type":"text"},"event_type":"step.delta"}

